{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.attr_status_code AS client_status, (s.span_id IS NOT NULL) AS reached_basic, count(*) AS n, avg(c.duration)/1e6 AS client_ms, avg(s.duration)/1e6 AS server_ms FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.service_name='ts-basic-service' WHERE c.service_name='ts-preserve-service' AND c.span_name='POST' AND c.attr_span_kind='Client' GROUP BY 1,2",
          "claim": "Preserve's failing client POSTs average about 4 ms and never reach ts-basic-service; the successful ones do not reach it either."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS c FROM abnormal_logs WHERE level='SEVERE' GROUP BY 1,2,3 ORDER BY c DESC",
          "claim": "ts-preserve-service logs 283 SEVERE errors: I/O error on POST to ts-basic-service /basic/travel, 'Unexpected end of file from server'."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS m, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, round(quantile_cont(duration/1e6,0.5),1) AS p50_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server' GROUP BY 1 ORDER BY 1",
          "claim": "Every ts-preserve-service /preserve server span is an error from the first minute of the incident onward."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS callee, c.service_name AS caller, c.span_name, count(*) AS n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) AS caller_errs, avg(c.duration)/1e6 AS caller_ms FROM abnormal_traces c JOIN abnormal_traces p ON p.parent_span_id = c.span_id WHERE c.service_name='ts-ui-dashboard' AND c.span_name='POST /api/v1/preserveservice/preserve' AND p.service_name='ts-preserve-service' GROUP BY ALL",
          "claim": "ts-ui-dashboard's POST /preserve spans return 500 after calling ts-preserve-service, which errored, averaging about 18.7 s."
        }
      ]
    }
  ]
}
